//! `vectors/hll.json` runner: NIP-45 HLL eligibility, offset
//! derivation, and register updates generated by go-nostr's
//! `nip45/hyperloglog` (v0.52.3).

#![allow(
    unused_crate_dependencies,
    reason = "each test binary uses a subset of the workspace dependencies"
)]
#![allow(
    clippy::tests_outside_test_module,
    reason = "each file is a single vector runner or property test"
)]
#![allow(
    clippy::expect_used,
    clippy::unwrap_used,
    clippy::panic,
    clippy::indexing_slicing,
    reason = "vector fixtures may panic on failure"
)]
#![allow(
    clippy::shadow_unrelated,
    reason = "the loop variables intentionally shadow per-case bindings"
)]

mod common;

use nosfry_core::event::PublicKey;
use nosfry_core::filter::Filter;
use nosfry_core::hll::Hll;
use serde::Deserialize;

#[derive(Deserialize)]
struct Case {
    filters: Vec<serde_json::Value>,
    offset: Option<usize>,
    #[serde(default)]
    pubkeys: Vec<String>,
    registers: Option<String>,
}

#[test]
fn hll() {
    let cases = common::cases::<Case>("hll.json");
    assert_eq!(cases.len(), 13, "vector count drift");
    for (i, case) in cases.iter().enumerate() {
        let filters: Vec<Filter> = case
            .filters
            .iter()
            .map(|f| {
                Filter::parse(&serde_json::to_string(f).expect("filter json"))
                    .unwrap_or_else(|e| panic!("case {i} filter: {e}"))
            })
            .collect();
        let Some(offset) = case.offset else {
            assert!(
                Hll::for_filters(&filters).is_none(),
                "case {i} unexpectedly eligible"
            );
            continue;
        };
        let mut hll = Hll::for_filters(&filters)
            .unwrap_or_else(|| panic!("case {i} unexpectedly ineligible"));
        assert_eq!(hll.offset(), offset, "case {i} offset");
        for pk in &case.pubkeys {
            let bytes: [u8; 32] = common::hex_decode(pk)
                .and_then(|v| v.try_into().ok())
                .unwrap_or_else(|| panic!("case {i} pubkey {pk}"));
            hll.add(&PublicKey(bytes));
        }
        let expected = common::hex_decode(
            case.registers
                .as_ref()
                .unwrap_or_else(|| panic!("case {i} missing registers")),
        )
        .unwrap_or_else(|| panic!("case {i} registers hex"));
        assert_eq!(hll.registers().as_slice(), expected.as_slice(), "case {i}");
    }
}
